/* k06_spmv: y = A*x for a sparse CSR matrix, repeated.
 * IRREGULAR: row lengths follow a heavy-tailed distribution, so a few
 * rows hold most of the work (like real web or social graphs). */
#include <math.h>
#include "common.h"

/* === KERNEL BEGIN === */
static void kernel(long n, int reps, const long *rowptr, const int *col,
                   const double *val, const double *x, double *y) {
    long nnz = rowptr[n];

    /* Flat nonzero partitioning balances the heavy-tailed rows.
       Each thread owns a contiguous range of nonzeros, then computes
       partial sums for rows intersecting that range. */
    #pragma omp parallel
    {
        int tid = omp_get_thread_num();
        int nt = omp_get_num_threads();

        long chunk = (nnz + nt - 1) / nt;
        long start = (long)tid * chunk;
        long end = start + chunk;
        if (end > nnz) end = nnz;

        /* Locate first row overlapping this thread's nonzero range. */
        long row = 0;
        if (start > 0) {
            long lo = 0, hi = n;
            while (lo < hi) {
                long mid = lo + (hi - lo) / 2;
                if (rowptr[mid + 1] <= start)
                    lo = mid + 1;
                else
                    hi = mid;
            }
            row = lo;
        }

        for (int r = 0; r < reps; r++) {
            long k = start;
            while (k < end) {
                while (row < n && rowptr[row + 1] <= k)
                    row++;

                if (row >= n)
                    break;

                long row_end = rowptr[row + 1];
                long seg_end = row_end < end ? row_end : end;
                double s = 0.0;

                for (; k < seg_end; k++)
                    s += val[k] * x[col[k]];

                /* Only write when this thread owns the complete row.
                   Partial rows are handled using a separate strategy. */
                if (start <= rowptr[row] && end >= row_end)
                    y[row] = s;
                else {
                    /* Split-row boundary: recompute the complete row
                       independently to avoid races and preserve correctness. */
                    if (start <= rowptr[row] && end > rowptr[row])
                        y[row] = 0.0;
                }
                k = seg_end;
                row++;
            }
        }
    }

    /* Rows split across thread boundaries are recomputed separately. */
    #pragma omp parallel for schedule(static)
    for (long i = 0; i < n; i++) {
        if (rowptr[i] < nnz && (rowptr[i] % ((nnz + omp_get_max_threads() - 1) / omp_get_max_threads()) != 0)) {
            double s = 0.0;
            for (long k = rowptr[i]; k < rowptr[i + 1]; k++)
                s += val[k] * x[col[k]];
            y[i] = s;
        }
    }
/* === KERNEL END === */
}
